  function storeAction(action){
    if(!action.startsWith('store'))return false;
    if(mobileLoggedOut||!['hotel_admin','hotel_operator'].includes(state.role))return true;
    if(storeSubmitting)return true;
    var id=action.split(':')[1],p=syncData.products.find(function(item){return item.id===id;});
    if(action.startsWith('storePlus:')||action.startsWith('storeMinus:')){if(!p||(p.status&&p.status!=='ACTIVE'))return true;var next=Math.max(0,(mobileCart[id]||0)+(action.startsWith('storePlus:')?1:-1));if(next>p.stock){showToast('库存仅剩 '+p.stock+' 件');return true;}mobileCart[id]=next;render();return true;}
    var b=storeBasket();if(!b.count)return true;
    if(action==='storeConfirm'){modalShell('确认商城订单','商城','<p>共 '+b.count+' 件，合计 '+money(b.cents/100)+'。</p>',button('取消','closeModal','secondary-button')+button('确定','storeSubmit','primary-button'));return true;}
    if(action==='storeSubmit'){
      var h=catHotel(),invalid=b.lines.find(function(p){return (p.status&&p.status!=='ACTIVE')||p.stock<mobileCart[p.id];});
      if(!h.active||invalid||syncBalance(h.id)<b.cents){closeModal();showToast(!h.active?'酒店已停用':invalid?invalid.name+'库存不足或已下架':'预付余额不足');return true;}
      var quantities=Object.assign({},mobileCart);storeSubmitting=true;closeModal();render();
      setTimeout(function(){var no='SO'+Date.now();b.lines.forEach(function(p){p.stock-=quantities[p.id];p.used=true;});syncData.balances[h.id]=syncBalance(h.id)-b.cents;syncData.entries.unshift({hotel:h.id,cents:-b.cents,after:syncData.balances[h.id],bank:no,type:'商城订单扣款',time:new Date().toLocaleString('zh-CN')});syncData.storeOrders=syncData.storeOrders||[];syncData.storeOrders.unshift({no:no,lines:b.lines.map(function(p){return p.name+' × '+quantities[p.id];}).join('、'),count:b.count,cents:b.cents,time:new Date().toLocaleString('zh-CN')});mobileCart={};storeSubmitting=false;syncSave();render();if(mobileLoggedOut)return;modalShell('订单已提交','商城','<p>订单号 '+no+'</p>',button('确定','closeModal','primary-button'));},350);return true;
    }return false;
  }

